297	/// Extract the dispatch-table `.word` entries from an assembly source between
298	/// `dispatch_table:` and the next `; ====` separator.
299	fn dispatch_entries(src: &str) -> Vec<String> {
300	    let mut in_table = false;
301	    let mut entries = Vec::new();
302	    for line in src.lines() {
303	        let trimmed = line.trim();
304	        if trimmed == "dispatch_table:" {
305	            in_table = true;
306	            continue;
307	        }
308	        if !in_table {
309	            continue;
310	        }
311	        if trimmed.starts_with("; ====") {
312	            break;
313	        }
314	        if trimmed.starts_with(".word ") {
315	            entries.push(trimmed.to_string());
