321	/// Extract the bounds-check constant from `lc r2, <N>` that precedes
322	/// `brt opcode_ok`.
323	fn bounds_check_value(src: &str) -> Option<u32> {
324	    let lines: Vec<&str> = src.lines().collect();
325	    for (i, line) in lines.iter().enumerate() {
326	        if line.contains("brt opcode_ok") {
327	            for j in (0..i).rev() {
328	                let t = lines[j].trim();
329	                if t.starts_with("lc r2,") {
330	                    let val = t.strip_prefix("lc r2,")?.trim();
331	                    return val.parse().ok();
332	                }
333	            }
334	        }
335	    }
336	    None
337	}
