        ("lt", 0x22, 1),
        ("le", 0x23, 1),
        ("gt", 0x24, 1),
        ("ge", 0x25, 1),
        // Control flow (0x30-0x36)
        ("jmp", 0x30, 4),
        ("jz", 0x31, 4),
        ("jnz", 0x32, 4),
        ("call", 0x33, 4),
        ("ret", 0x34, 2),
        ("calln", 0x35, 5),
        ("trap", 0x36, 2),
        // Local/Global/Nonlocal (0x40-0x4B)
        ("enter", 0x40, 2),
        ("leave", 0x41, 1),
        ("loadl", 0x42, 2),
        ("storel", 0x43, 2),
        ("loadg", 0x44, 4),
        ("storeg", 0x45, 4),
