fn load_p24_errors() {
    // Too short
    assert!(matches!(load_p24(&[]), Err(LoadError::TooShort)));
    assert!(matches!(load_p24(&[0; 10]), Err(LoadError::TooShort)));

    // Bad magic
    let mut bad = vec![0u8; 18];
