    assert!(matches!(load_p24(&bad), Err(LoadError::BadVersion(99))));

    // Truncated
    bad[4] = P24_VERSION;
    bad[8] = 10; // code_size = 10 but body is empty
    assert!(matches!(load_p24(&bad), Err(LoadError::Truncated)));
}

