        // Control flow
        assert_eq!(Opcode::Jmp as u8, 0x30);
        assert_eq!(Opcode::Jz as u8, 0x31);
        assert_eq!(Opcode::Jnz as u8, 0x32);
        assert_eq!(Opcode::Call as u8, 0x33);
