1	//! Core linker for pl24r — the COR24 p-code linker.
2	//!
3	//! Merges multiple parsed .spc modules into a single linked output,
4	//! ordering modules correctly and merging declarations by type.
5	//! Language-agnostic: operates on .spc files from any COR24 compiler frontend.
6	
7	use crate::parser::{Const, Data, Global, Item, Module, Proc, Statement};
8	
9	/// The merged output of linking multiple .spc modules.
10	#[derive(Debug, Clone, PartialEq)]
11	pub struct LinkedOutput {
12	    /// Header comments (preserved from all modules).
13	    pub comments: Vec<String>,
14	    /// Merged global declarations.
15	    pub globals: Vec<Global>,
16	    /// Merged data declarations.
17	    pub data: Vec<Data>,
18	    /// Merged constant declarations.
19	    pub consts: Vec<Const>,
20	    /// All procedures in link order (runtime/libs first, main module last).
21	    pub procs: Vec<Proc>,
22	}
23	
24	/// Error encountered during linking.
25	#[derive(Debug, Clone, PartialEq)]
26	pub struct LinkError {
27	    pub message: String,
28	}
29	
30	impl std::fmt::Display for LinkError {
31	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
32	        write!(f, "{}", self.message)
33	    }
34	}
35	
36	impl std::error::Error for LinkError {}
37	
38	/// Link multiple parsed modules into a single merged output.
39	///
40	/// Modules are reordered: modules without `main` come first (in input order),
41	/// then the module containing `main` comes last as the entry point.
42	/// Linker-only metadata (.module, .endmodule, .export, .extern) is stripped.
43	pub fn link(modules: &[Module]) -> Result<LinkedOutput, Vec<LinkError>> {
44	    let mut errors = Vec::new();
45	
46	    // Find the app module (contains main).
47	    let main_index = modules.iter().position(|m| {
48	        m.items
49	            .iter()
50	            .any(|item| matches!(item, Item::Proc(p) if p.name == "main"))
51	    });
52	
53	    let Some(main_index) = main_index else {
54	        errors.push(LinkError {
55	            message: "no module contains a 'main' procedure".to_string(),
56	        });
57	        return Err(errors);
58	    };
59	
60	    // Order: main module first (VM starts execution at code offset 0),
61	    // then remaining modules in input order.
62	    let mut ordered: Vec<&Module> = Vec::with_capacity(modules.len());
63	    ordered.push(&modules[main_index]);
64	    for (i, m) in modules.iter().enumerate() {
65	        if i != main_index {
66	            ordered.push(m);
67	        }
68	    }
69	
70	    let mut comments = Vec::new();
71	    let mut globals = Vec::new();
72	    let mut data = Vec::new();
73	    let mut consts = Vec::new();
74	    let mut procs = Vec::new();
75	
76	    let mut seen_globals = std::collections::HashSet::new();
77	    let mut seen_consts = std::collections::HashMap::new();
78	
79	    for module in &ordered {
80	        // Add a module separator comment for debuggability.
81	        comments.push(format!("; --- module: {} ---", module.name));
82	
83	        for item in &module.items {
84	            match item {
85	                Item::Comment(c) => comments.push(c.clone()),
86	                Item::Global(g) => {
87	                    if seen_globals.insert(g.name.clone()) {
88	                        globals.push(g.clone());
89	                    }
90	                    // Duplicate globals with same name are silently merged
91	                    // (symbol table already validated no conflicts).
92	                }
93	                Item::Data(d) => {
94	                    data.push(d.clone());
95	                }
96	                Item::Const(c) => {
97	                    if let Some(prev_val) = seen_consts.get(&c.name) {
98	                        if *prev_val != c.value {
99	                            errors.push(LinkError {
100	                                message: format!(
101	                                    "conflicting constant '{}': '{}' vs '{}'",
102	                                    c.name, prev_val, c.value
103	                                ),
104	                            });
105	                        }
106	                    } else {
107	                        seen_consts.insert(c.name.clone(), c.value.clone());
108	                        consts.push(c.clone());
109	                    }
110	                }
111	                Item::Proc(p) => {
112	                    procs.push(p.clone());
113	                }
114	            }
115	        }
116	    }
117	
118	    if !errors.is_empty() {
119	        return Err(errors);
120	    }
121	
122	    Ok(LinkedOutput {
123	        comments,
124	        globals,
125	        data,
126	        consts,
127	        procs,
128	    })
129	}
130	
131	/// Emit a linked output as .spc text, ready for pasm.
132	pub fn emit(output: &LinkedOutput) -> String {
133	    let mut lines = Vec::new();
134	
135	    // Header comments.
136	    for c in &output.comments {
137	        lines.push(c.clone());
138	    }
139	    if !output.comments.is_empty() {
140	        lines.push(String::new());
141	    }
142	
143	    // Globals section.
144	    for g in &output.globals {
145	        lines.push(format!(".global {} {}", g.name, g.nwords));
146	    }
147	    if !output.globals.is_empty() {
148	        lines.push(String::new());
149	    }
150	
151	    // Data section.
152	    for d in &output.data {
153	        let bytes_str: Vec<String> = d.bytes.iter().map(|b| b.to_string()).collect();
154	        lines.push(format!(".data {} {}", d.name, bytes_str.join(",")));
155	    }
156	    if !output.data.is_empty() {
157	        lines.push(String::new());
158	    }
159	
160	    // Constants section.
161	    for c in &output.consts {
162	        lines.push(format!(".const {} {}", c.name, c.value));
163	    }
164	    if !output.consts.is_empty() {
165	        lines.push(String::new());
166	    }
167	
168	    // Procedures.
169	    for p in &output.procs {
170	        lines.push(format!(".proc {} {}", p.name, p.nlocals));
171	        for stmt in &p.body {
172	            match stmt {
173	                Statement::Label(l) => lines.push(format!("{l}:")),
174	                Statement::Instruction(i) => {
175	                    let mut s = format!("    {}", i.mnemonic);
176	                    if let Some(op) = &i.operand {
177	                        s.push(' ');
178	                        s.push_str(op);
179	                    }
180	                    if let Some(c) = &i.comment {
181	                        // Pad to align comments.
182	                        let pad = if s.len() < 24 { 24 - s.len() } else { 1 };
183	                        s.push_str(&" ".repeat(pad));
184	                        s.push_str(c);
185	                    }
186	                    lines.push(s);
187	                }
188	                Statement::Comment(c) => lines.push(format!("    {c}")),
189	                Statement::Blank => lines.push(String::new()),
190	            }
191	        }
192	        lines.push(".end".to_string());
193	        lines.push(String::new());
194	    }
195	
196	    lines.join("\n")
197	}
198	
