    #[test]
    fn test_parse_comment() {
        let src = "; this is a comment\n";
        let m = parse(src, "test.spc").unwrap();
        assert_eq!(m.items.len(), 1);
        assert_eq!(m.items[0], Item::Comment("; this is a comment".to_string()));
    }

