        let m = parse(src, "test.spc").unwrap();
        assert_eq!(m.items.len(), 1);
        match &m.items[0] {
            Item::Data(d) => {
                assert_eq!(d.name, "msg");
                assert_eq!(d.bytes, vec![72, 101, 108, 108, 111, 10, 0]);
            }
            _ => panic!("expected Data"),
        }
