    push ANSWER
    halt
.end
";
    let result = assemble(source);
    assert!(result.errors.is_empty(), "errors: {:?}", result.errors);
    // enter 0 (auto), push 42, halt, leave (auto)
    assert_eq!(result.code, vec![0x40, 0x00, 0x01, 42, 0, 0, 0x00, 0x41]);
