    assert_eq!(info.name, "mathlib");
    assert_eq!(info.exports.len(), 1);
    assert_eq!(info.exports[0].name, "double");

    // Code should match
    let result = assemble(source);
    assert_eq!(loaded.code, result.code);
    assert_eq!(loaded.data, result.data);
}

