#[test]
fn unit_mode_collects_exports() {
    // main does not have to be first — but we put it first here for simplicity.
    // See main_not_first_is_ok for the general case.
    let source = "\
.unit mathlib
.export add_nums 2

.proc main 0
    halt
.end

.proc add_nums 2
