        ("sub", 0x11, 1),
        ("mul", 0x12, 1),
        ("div", 0x13, 1),
        ("mod", 0x14, 1),
        ("neg", 0x15, 1),
        // Logic (0x16-0x1B)
        ("and", 0x16, 1),
        ("or", 0x17, 1),
        ("xor", 0x18, 1),
        ("not", 0x19, 1),
        ("shl", 0x1A, 1),
        ("shr", 0x1B, 1),
        // Comparison (0x20-0x25)
        ("eq", 0x20, 1),
        ("ne", 0x21, 1),
        ("lt", 0x22, 1),
        ("le", 0x23, 1),
        ("gt", 0x24, 1),
        ("ge", 0x25, 1),
        // Control flow (0x30-0x36)
        ("jmp", 0x30, 4),
        ("jz", 0x31, 4),
        ("jnz", 0x32, 4),
        ("call", 0x33, 4),
        ("ret", 0x34, 2),
        ("calln", 0x35, 5),
        ("trap", 0x36, 2),
        // Local/Global/Nonlocal (0x40-0x4B)
        ("enter", 0x40, 2),
        ("leave", 0x41, 1),
        ("loadl", 0x42, 2),
        ("storel", 0x43, 2),
        ("loadg", 0x44, 4),
        ("storeg", 0x45, 4),
        ("addrl", 0x46, 2),
        ("addrg", 0x47, 4),
        ("loada", 0x48, 2),
        ("storea", 0x49, 2),
        ("loadn", 0x4A, 3),
        ("storen", 0x4B, 3),
        // Memory indirect (0x50-0x53)
        ("load", 0x50, 1),
        ("store", 0x51, 1),
        ("loadb", 0x52, 1),
        ("storeb", 0x53, 1),
        // System (0x60)
        ("sys", 0x60, 2),
    ];

    for &(mnemonic, expected_byte, expected_size) in pvm_s_opcodes {
        let op = Opcode::from_mnemonic(mnemonic)
            .unwrap_or_else(|| panic!("mnemonic '{mnemonic}' not recognized"));
        assert_eq!(
