    #[test]
    fn test_link_ordering_main_first() {
        let app = parse_ok(
            "\
.module app
.export main
.extern _p24p_write_int

.proc main 0
    push 42
    call _p24p_write_int
    halt
.end

.endmodule
",
            "app.spc",
